    /**
     * Writes the terminal conversation, retrying a bounded number of times. Returns the last error when
     * every attempt failed so the caller can report it; the failure is never swallowed.
     */
    async persistTerminalConversation(run) {
        for (let attempt = 1; attempt <= TERMINAL_PERSIST_ATTEMPTS; attempt += 1) {
            try {
                await this.persistConversation(run);
                logAgentEvent('[agent:terminalPersist]', {
                    attempt,
                    conversationId: run.conversation.id,
                    runId: run.id,
                    status: run.conversation.status,
                    persisted: true,
                });

                return null;
            } catch (error) {
                logAgentEvent('[agent:terminalPersist]', {
                    attempt,
                    conversationId: run.conversation.id,
                    error: error instanceof Error ? error.message : String(error),
                    runId: run.id,
                    status: run.conversation.status,
                    persisted: false,
                });
                if (attempt === TERMINAL_PERSIST_ATTEMPTS) return error;
            }
        }

        return null;
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: snapshotConversation(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    persistSuccessfulTurn(run) {
        const snapshot = { ...run, conversation: snapshotConversation(run.conversation) };
        const write = run.persistence.then(() => this.persistSuccessfulConversationTurn(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
